<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class LanguageTuitionCharge extends Model { protected $guarded=[]; protected $casts=['due_date'=>'date','original_amount'=>'decimal:2','discount_percentage'=>'decimal:2','discount_amount'=>'decimal:2','payable_amount'=>'decimal:2','paid_amount'=>'decimal:2','credit_amount'=>'decimal:2']; public function student(){return $this->belongsTo(LanguageStudent::class,'language_student_id')->withTrashed();} public function lead(){return $this->belongsTo(LanguageLead::class,'language_lead_id')->withTrashed();} public function course(){return $this->belongsTo(LanguageCourse::class,'language_course_id')->withTrashed();} public function languageClass(){return $this->belongsTo(LanguageClass::class,'language_class_id')->withTrashed();} public function discount(){return $this->belongsTo(LanguageDiscountPolicy::class,'language_discount_policy_id')->withTrashed();} public function payments(){return $this->hasMany(LanguageTuitionPayment::class);} public function incomingTransfers(){return $this->hasMany(LanguageClassTransfer::class,'to_tuition_charge_id');} public function outgoingTransfers(){return $this->hasMany(LanguageClassTransfer::class,'from_tuition_charge_id');} public function remainingAmount():float{return max(0,(float)$this->payable_amount-(float)$this->paid_amount-(float)$this->credit_amount);} }
